package glitch

import data.glitch_lib

password_pattern := `(?i)(^|_)(password|passwd|pwd|pass|secret|credential|credentials|auth_password|db_password|database_password|db_pass|admin_password|root_password|user_password|secret_key|shared_secret|service_password|account_password)($|_)`

is_empty_value(value) {
    value.ir_type == "String"
    regex.match(`^\s*$`, value.value)
}

is_empty_value(value) {
    value.ir_type == "Null"
}

is_empty_value(value) {
    value.ir_type == "Undef"
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    regex.match(password_pattern, attr.name)
    is_empty_value(attr.value)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in configuration file - Credential-related fields should not be assigned empty, null, or blank values. (CWE-258)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    v := vars[_]

    regex.match(password_pattern, v.name)
    is_empty_value(v.value)

    result := {
        "type": "sec_empty_pass",
        "element": v,
        "path": parent.path,
        "description": "Empty password in configuration file - Credential-related fields should not be assigned empty, null, or blank values. (CWE-258)"
    }
}

